  function loadState() {
    return window.PM7_SETTINGS_TOME.load(clone(defaultState), mergeState);
  }

  function mergeState(base, saved) {
    if (!saved || typeof saved !== 'object') return base;
    const merge = (target, source) => {
      for (const [key, val] of Object.entries(source)) {
        if (val && typeof val === 'object' && !Array.isArray(val) && target[key] && typeof target[key] === 'object' && !Array.isArray(target[key])) {
          merge(target[key], val);
        } else if (val !== undefined) target[key] = val;
      }
      return target;
    };
    return merge(base, saved);
  }

  let state = loadState();

  function saveState() {
    searchIndexDirty = true;
    const copy = clone(state);
    delete copy.home; delete copy.railOpen; delete copy.resourceRosterOpen;
    window.PM7_SETTINGS_TOME.save(copy);
  }


