  function handleInputAction(action, el) {
    if (action === 'all-settings-query') {allSettingsView.query=el.value;clearTimeout(allSettingsQueryTimer);allSettingsQueryTimer=setTimeout(()=>{allSettingsQueryTimer=0;refreshAllSettingsVirtual(true);},80);return;}
    if (action === 'input-setting') {
      const id=ds(el,'setting'),found=findSettingGlobal(id),suffix=ds(el,'valueSuffix','');const next=suffix?`${el.value}${suffix}`:(found&&typeof found.setting.value==='number'?Number(el.value):el.value);if(!commitSettingValue(id,next))return;const output=el.closest('.slider-control')?.querySelector('output');if(output)output.textContent=suffix?`${el.value}${suffix}`:el.value;saveState();return;
    }
    if (action === 'filter-roster') {
      const q=el.value.trim().toLowerCase();
      const map={providers:'provider-roster','web-routes':'web-route-roster','media-routes':'media-route-roster',toolchain:'toolchain-roster'};
      const container=root.querySelector('#'+cssEscape(map[ds(el,'roster')]||ds(el,'roster')));
      container?.querySelectorAll('[data-filter-text]').forEach(row=>{row.hidden=!!q&&!row.dataset.filterText.includes(q);});return;
    }
    if (action === 'filter-memory-list') {
      const q=el.value.trim().toLowerCase();root.querySelectorAll('#memory-list [data-filter-text]').forEach(row=>{row.hidden=!!q&&!row.dataset.filterText.includes(q);});return;
    }
    if (action === 'persona-search') {
      state.personaQuery=el.value;saveState();const q=el.value.trim().toLowerCase();
      const list=el.closest('.filter-row')?.nextElementSibling?.querySelector('.library-list-scroll');
      list?.querySelectorAll('.library-item').forEach(row=>{row.hidden=!!q&&!row.textContent.toLowerCase().includes(q);});return;
    }
  }

