      title: g.name, pill: PM51.status(g.status === 'active' ? 'Ready' : 'Off'),
      meta: `${g.events.join(', ')} · ${g.escalation === 'None' ? 'No escalation' : g.escalation}`,
      end: icon('chevron'), action: 'pm51-notifications-group', data: { id: g.id }
